*{box-sizing:border-box} :root{--ink:#f7f4e9;--muted:rgba(238,242,229,.62);--gold:#e7c889;--glass:rgba(10,27,34,.68);--line:rgba(244,239,222,.16)}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#081c25;color:var(--ink);font-family:'DM Sans',sans-serif}button{font:inherit;color:inherit;cursor:pointer}.game-shell{position:relative;width:100%;height:100dvh;min-height:540px;overflow:hidden;background:#102d38}#world{position:absolute;inset:0;width:100%;height:100%;display:block}.scene-vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(5,20,27,.56) 0%,transparent 23%,transparent 57%,rgba(4,17,23,.32) 100%),linear-gradient(90deg,rgba(6,19,23,.39),transparent 25%,transparent 75%,rgba(5,18,23,.16))}.topbar{position:absolute;z-index:2;left:0;right:0;top:0;height:86px;padding:0 40px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.1);background:linear-gradient(180deg,rgba(7,22,28,.32),transparent)}.brand{display:flex;align-items:center;gap:11px;text-decoration:none;color:var(--ink)}.brand-mark{width:37px;height:37px;border:1px solid rgba(231,200,137,.64);border-radius:50%;display:grid;place-items:center;font-family:'Playfair Display',serif;color:#f1d59d;font-size:23px}.brand-mark span{color:#d79565}.brand-name{font-size:12px;letter-spacing:2px;font-weight:700}.brand-name small{display:block;color:rgba(241,238,222,.52);font-size:8px;letter-spacing:3.3px;margin-top:3px}.location{display:flex;align-items:center;gap:12px;margin-left:10%;margin-right:auto}.live-dot,.session-dot{width:7px;height:7px;border-radius:50%;background:#c9dcab;box-shadow:0 0 11px #c9dcab;display:inline-block}.location strong{font-size:10px;letter-spacing:1.6px}.location small{display:block;color:var(--muted);font-size:9px;letter-spacing:1px;margin-top:4px}.top-actions{display:flex;align-items:center;gap:15px}.icon-button{width:35px;height:35px;border-radius:50%;border:1px solid var(--line);background:rgba(8,25,32,.4);font-size:17px;color:#e7d8b8}.profile{display:flex;align-items:center;gap:9px;border:0;background:transparent;text-align:left;font-size:9px;letter-spacing:1.2px}.profile>span{display:grid;place-items:center;width:34px;height:34px;border-radius:50%;background:#d7c19a;color:#24302a;font:700 14px 'Playfair Display',serif}.profile small{display:block;color:var(--muted);font-size:8px;margin-top:3px}.profile i{font-style:normal;color:var(--muted);font-size:15px;margin-left:6px}.left-rail{position:absolute;z-index:2;left:40px;top:112px;width:185px;display:flex;flex-direction:column;gap:10px}.rail-card{background:var(--glass);backdrop-filter:blur(15px);border:1px solid rgba(255,255,255,.14);border-radius:3px;box-shadow:0 10px 35px rgba(0,0,0,.1)}.weather-card{padding:14px 15px 12px}.eyebrow{display:block;color:rgba(235,236,218,.56);font-size:8px;letter-spacing:1.4px}.weather{display:flex;align-items:center;gap:12px;margin:12px 0 13px}.sun-icon{font-size:23px;color:#efd79f;text-shadow:0 0 17px rgba(245,204,120,.5)}.weather b{font:600 19px 'Playfair Display',serif}.weather small{display:block;color:rgba(236,237,222,.63);font-size:8px;letter-spacing:1.2px;margin-top:2px}.weather-line{display:flex;justify-content:space-between;border-top:1px solid rgba(255,255,255,.1);padding-top:8px;margin-top:7px;font-size:8px;letter-spacing:.7px;color:rgba(236,237,222,.58)}.weather-line b{color:#f0edde;font-size:8px;letter-spacing:.8px}.map-card,.journal-card{padding:13px 15px;background:var(--glass);text-align:left;width:100%}.map-card .eyebrow,.journal-card .eyebrow{display:flex;justify-content:space-between}.arrow{font-size:13px;color:#e5ca93}.map-thumb{height:67px;position:relative;overflow:hidden;margin:11px 0 9px;border:1px solid rgba(255,255,255,.17);background:linear-gradient(145deg,#334a3d,#75826a 45%,#344b45 46%,#24434a);}.map-thumb:before,.map-thumb:after{content:'';position:absolute;inset:-25%;background:repeating-linear-gradient(45deg,transparent 0 17px,rgba(223,215,163,.16) 18px 19px,transparent 20px 35px);transform:rotate(-20deg)}.map-river{position:absolute;z-index:1;width:145%;height:20px;top:24px;left:-18%;background:#78a7a5;transform:rotate(-24deg);border-radius:50%;box-shadow:0 0 12px rgba(133,194,182,.42)}.map-pin{position:absolute;z-index:2;left:55%;top:26px;font-size:18px;color:#ffe1a3;text-shadow:0 1px 5px #172a26}.map-label{font-size:10px;color:#f4f0e2}.map-label b{float:right;color:#e8c98c;font-size:15px;line-height:10px}.journal-progress{display:flex;align-items:center;margin-top:12px}.journal-progress>b{font:28px 'Playfair Display',serif;color:#e6d2a8}.journal-progress>span:nth-child(2){font-size:10px;color:#f1ebdc;padding-left:4px}.journal-progress small{display:block;font-size:7px;color:var(--muted);letter-spacing:1px;margin-top:3px}.progress-ring{margin-left:auto;width:33px;height:33px;border-radius:50%;border:3px solid rgba(255,255,255,.18);border-top-color:#e4c384;border-right-color:#e4c384;transform:rotate(22deg)}.mini-fish{margin-top:9px;padding-top:8px;border-top:1px solid rgba(255,255,255,.1);font-size:11px;color:#efce8c}.mini-fish span{font-size:8px;color:var(--muted);margin-left:5px}.right-rail{position:absolute;z-index:2;top:105px;right:40px;display:flex;align-items:center;gap:11px}.session-pill{display:flex;align-items:center;gap:9px;padding:9px 12px;background:var(--glass);backdrop-filter:blur(12px);border:1px solid var(--line);border-radius:3px;font-size:9px;color:#f2ecdc}.session-dot{width:5px;height:5px}.pill-divider{height:13px;border-left:1px solid var(--line)}.session-pill b{font-size:9px;font-weight:500;color:#e6cf9d}.catch-streak{height:34px;padding:0 10px;display:flex;align-items:center;gap:7px;background:var(--glass);border:1px solid var(--line)}.streak-icon{color:#e8c986;font-size:15px}.catch-streak b{font-size:12px}.catch-streak small{display:block;font-size:7px;letter-spacing:1px;color:var(--muted)}.spot-card{position:absolute;z-index:1;left:40px;bottom:144px;width:300px;text-shadow:0 2px 20px rgba(0,0,0,.44)}.spot-kicker{font-size:8px;letter-spacing:1.7px;color:#f1d59d}.spot-kicker span{font-size:12px;margin-right:6px}.spot-card h1{font:600 37px/1.07 'Playfair Display',serif;letter-spacing:-.7px;margin:9px 0 10px}.spot-card p{color:rgba(247,245,232,.74);font-size:10px;line-height:1.7;margin:0}.spot-meta{display:flex;gap:17px;margin-top:15px;font-size:8px;letter-spacing:.8px;color:#e8d9b8}.depth-card{position:absolute;z-index:2;right:40px;bottom:152px;width:220px;padding:11px 12px 9px;background:var(--glass);backdrop-filter:blur(12px);border:1px solid var(--line)}.depth-head{display:flex;justify-content:space-between;font-size:8px;letter-spacing:1px;color:rgba(240,239,222,.7)}.depth-head span:last-child{color:#e8cc92}.depth-graphic{height:54px;position:relative;margin-top:7px;overflow:hidden}.depth-grid{position:absolute;inset:0;background:repeating-linear-gradient(0deg,transparent 0 13px,rgba(255,255,255,.08) 14px),repeating-linear-gradient(90deg,transparent 0 43px,rgba(255,255,255,.07) 44px)}.depth-graphic svg{position:absolute;width:100%;height:100%;inset:0}.depth-fill{fill:rgba(124,175,169,.21)}.depth-path{fill:none;stroke:#b1d1be;stroke-width:1.4;vector-effect:non-scaling-stroke}.depth-marker{position:absolute;left:57%;top:0;bottom:0;border-left:1px dashed #ecd293}.depth-legend{display:flex;justify-content:space-between;color:rgba(236,236,218,.47);font-size:6px;letter-spacing:.8px;margin-top:3px}.rod-hud{position:absolute;z-index:2;left:50%;transform:translateX(-50%);bottom:128px;width:245px;height:41px;border-top:1px solid rgba(255,255,255,.19);display:flex;align-items:center;justify-content:space-between}.rod-label{display:flex;align-items:center;gap:8px}.rod-icon{font-size:20px;color:#e1c48b}.rod-label b{display:block;font-size:8px;letter-spacing:1.1px}.rod-label small{display:block;color:var(--muted);font-size:7px;letter-spacing:.7px;margin-top:3px}.line-status{display:flex;align-items:center;gap:5px;font-size:7px;letter-spacing:.8px;color:rgba(238,238,222,.66)}.line-dot{width:5px;height:5px;border-radius:50%;background:#c6d6ad}.center-message{position:absolute;z-index:2;left:50%;top:43%;transform:translate(-50%,-50%);text-align:center;pointer-events:none;text-shadow:0 2px 18px rgba(0,0,0,.55);transition:opacity .3s}.center-message .message-icon{display:block;color:rgba(242,219,168,.85);font-size:19px;margin-bottom:8px}.center-message>span:nth-child(2){font:20px 'Playfair Display',serif}.center-message small{display:block;font-size:9px;color:rgba(244,242,227,.76);letter-spacing:1px;margin-top:6px}.action-zone{position:absolute;z-index:3;left:50%;bottom:46px;transform:translateX(-50%);width:270px;display:grid;place-items:center}.cast-button{width:214px;height:54px;display:flex;align-items:center;gap:10px;padding:0 15px;background:linear-gradient(130deg,#d9c18f,#efd7a7);border:1px solid rgba(255,244,204,.7);border-radius:2px;color:#25332c;box-shadow:0 6px 25px rgba(0,0,0,.2);transition:transform .2s,filter .2s}.cast-button:hover{transform:translateY(-2px);filter:brightness(1.08)}.cast-symbol{font-size:18px}.cast-text{text-align:left;font-size:10px;font-weight:700;letter-spacing:1.5px}.cast-text small{display:block;font-size:7px;opacity:.65;letter-spacing:1px;margin-top:3px}.cast-arrow{margin-left:auto;font-size:17px}.reel-button{display:none;width:214px;height:54px;background:#d9c18f;border:0;color:#25332c;letter-spacing:1.8px;font-size:11px;font-weight:700}.reel-button.active{display:block}.reel-button:active{background:#f1d9a8}.tension-wrap{display:none;width:265px;margin-bottom:13px;padding:10px 12px;background:rgba(9,26,31,.81);border:1px solid rgba(255,255,255,.18);backdrop-filter:blur(12px)}.tension-wrap.active{display:block}.tension-copy{display:flex;justify-content:space-between;font-size:7px;letter-spacing:1.3px}.tension-copy b{color:#c7d7b1}.tension-track{position:relative;margin-top:8px;height:5px;background:linear-gradient(90deg,#87ad91 0 54%,#e0ca8d 54% 76%,#c77d63 76% 100%);border-radius:4px}.tension-track i{position:absolute;left:5%;top:-3px;width:3px;height:11px;background:white;box-shadow:0 0 5px white;transition:left .2s}.tension-track span{position:absolute;left:54%;height:100%;border-left:1px solid rgba(10,20,18,.5)}.tension-track span:last-child{left:76%}.tension-wrap>small{display:block;color:var(--muted);font-size:7px;margin-top:7px}.bottom-hint{position:absolute;z-index:2;bottom:14px;left:50%;transform:translateX(-50%);white-space:nowrap;font-size:7px;letter-spacing:1px;color:rgba(244,240,220,.61)}.bottom-hint span{color:#f2d89e;font-weight:700}.bottom-hint i{font-style:normal;margin:0 8px;color:rgba(255,255,255,.37)}.toast{position:absolute;z-index:7;top:94px;left:50%;transform:translate(-50%,-12px);opacity:0;padding:10px 16px;background:rgba(12,30,34,.92);border:1px solid rgba(236,215,166,.38);font-size:10px;letter-spacing:.6px;transition:.3s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.modal-backdrop{position:absolute;z-index:8;inset:0;background:rgba(5,15,19,.65);backdrop-filter:blur(8px);display:none;align-items:center;justify-content:center;padding:20px}.modal-backdrop.open{display:flex}.modal{position:relative;width:min(570px,100%);max-height:85vh;overflow:auto;background:#122b31;border:1px solid rgba(230,205,153,.37);box-shadow:0 25px 90px #0008;padding:31px;color:#f3efdf}.modal-close{position:absolute;right:16px;top:12px;background:transparent;border:0;color:#e5d7b7;font-size:25px}.modal-kicker{color:#e2c88f;font-size:8px;letter-spacing:2px}.modal h2{font:30px 'Playfair Display',serif;margin:8px 0 5px}.modal-intro{font-size:11px;color:var(--muted);line-height:1.6;margin:0 0 20px}.species-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.species-item{min-height:82px;padding:12px;background:#1a363a;border:1px solid rgba(255,255,255,.08)}.species-item .fish-emoji{font-size:19px}.species-item b{display:block;font-size:9px;margin:5px 0 3px}.species-item small{font-size:7px;letter-spacing:.7px;color:var(--muted)}.species-item.locked{opacity:.42;filter:grayscale(1)}.map-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.map-option{position:relative;text-align:left;min-height:105px;padding:14px;border:1px solid rgba(255,255,255,.14);background:linear-gradient(140deg,#335648,#233f44 55%,#1d353e);}.map-option:nth-child(2){background:linear-gradient(140deg,#966447,#454744 55%,#31505a)}.map-option:nth-child(3){background:linear-gradient(140deg,#5b6863,#273b43 55%,#16333f)}.map-option:nth-child(4){background:linear-gradient(140deg,#406578,#263e4d 55%,#1b303a)}.map-option.selected{border-color:#e5c986;box-shadow:inset 0 0 0 1px #e5c986}.map-option b{display:block;font:17px 'Playfair Display',serif;margin-bottom:5px}.map-option span{font-size:8px;letter-spacing:.8px;color:rgba(246,239,219,.75)}.map-option .map-lock{position:absolute;right:12px;top:12px;color:#e7cd95}.catch-result{text-align:center}.trophy{font-size:40px;color:#ecd39b;margin:4px}.catch-result h2{font-size:32px}.catch-result .catch-fish{font:italic 16px 'Playfair Display',serif;color:#e4ca94}.catch-stats{display:flex;justify-content:center;gap:24px;padding:18px;margin:17px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.catch-stats b{display:block;font-size:16px}.catch-stats small{font-size:7px;letter-spacing:1px;color:var(--muted)}.modal-action{padding:12px 22px;background:#e4cb98;border:0;color:#23342e;font-size:9px;font-weight:700;letter-spacing:1.4px}
@media(max-width:850px){.topbar{padding:0 20px;height:68px}.left-rail{left:20px;top:84px;width:165px}.right-rail{top:82px;right:20px}.spot-card{left:20px;bottom:146px;width:250px}.depth-card{right:20px;bottom:149px;width:190px}.rod-hud{bottom:121px}.location{margin-left:5%;}.profile strong{display:none}.scene-vignette{background:linear-gradient(180deg,rgba(5,20,27,.55),transparent 24%,transparent 55%,rgba(4,17,23,.42))}}@media(max-width:600px){.game-shell{min-height:480px}.topbar{height:60px;padding:0 13px}.brand{gap:7px}.brand-mark{width:31px;height:31px;font-size:20px}.brand-name{font-size:10px;letter-spacing:1.5px}.brand-name small{font-size:7px}.location{margin:0;gap:6px}.location strong{font-size:8px;letter-spacing:1px}.location small{font-size:7px;letter-spacing:.4px}.top-actions{gap:5px}.profile{padding:0}.profile>span{width:29px;height:29px}.profile i{display:none}.icon-button{width:30px;height:30px}.left-rail{left:12px;top:72px;width:137px;gap:6px}.rail-card{backdrop-filter:blur(8px)}.weather-card{padding:10px}.weather{margin:8px 0}.map-card,.journal-card{padding:9px 10px}.map-thumb{height:47px;margin:7px 0}.map-river{top:14px}.map-pin{top:15px}.map-label{font-size:9px}.journal-progress{margin-top:7px}.journal-progress>b{font-size:23px}.progress-ring{width:27px;height:27px}.mini-fish{margin-top:6px;padding-top:6px;font-size:9px}.mini-fish span{font-size:7px}.right-rail{right:12px;top:72px;gap:5px}.session-pill{padding:7px;gap:6px;font-size:7px}.catch-streak{height:29px;padding:0 6px}.spot-card{left:15px;bottom:125px;width:200px}.spot-card h1{font-size:29px}.spot-card p{font-size:8px}.spot-meta{font-size:7px;gap:8px;margin-top:9px}.depth-card{right:12px;bottom:126px;width:155px;padding:8px}.depth-graphic{height:40px}.rod-hud{bottom:101px;width:220px;height:34px}.action-zone{bottom:38px;width:235px}.cast-button,.reel-button{width:190px;height:45px}.tension-wrap{width:235px;margin-bottom:8px}.bottom-hint{bottom:12px;font-size:6px;letter-spacing:.4px}.bottom-hint i{margin:0 3px}.center-message{top:40%}.center-message>span:nth-child(2){font-size:17px}.toast{top:68px}.modal{padding:25px 18px}.species-grid{grid-template-columns:repeat(2,1fr)}.map-grid{gap:7px}.map-option{min-height:92px;padding:10px}.map-option b{font-size:15px}}
@media(max-height:650px){.left-rail{top:82px;gap:6px}.weather-card{padding:9px 12px}.weather{margin:6px 0}.weather-line{padding-top:5px;margin-top:5px}.map-thumb{height:48px;margin:7px 0}.spot-card{bottom:119px}.depth-card{bottom:127px}.rod-hud{bottom:101px}.action-zone{bottom:32px}.bottom-hint{bottom:8px}}

(() => {
  const canvas=document.getElementById('world'),ctx=canvas.getContext('2d');
  const $=id=>document.getElementById(id);
  const maps=[
    {name:'MIRROR LAKE',detail:'PACIFIC NORTHWEST · 06:42 AM',spot:'The Glass<br>Water',copy:'A hidden pocket beneath the pines.<br>Take your time. The lake is listening.',temp:'18°',weather:'CLEAR SKIES',water:'14° C',depth:'6.4 m',sky:['#d4b68c','#8eb1a8','#547b78'],hills:['#435a4e','#344940','#243d3c'],water:'#406c70',fish:[['Rainbow Trout','Brook Trout','Largemouth Bass','Yellow Perch','Northern Pike','Bluegill','Lake Sturgeon','Walleye','Brown Trout','Smallmouth Bass','Whitefish','Muskellunge','Kokanee Salmon','Catfish','Tiger Trout','Bull Trout','Arctic Char','Golden Trout']]},
    {name:'REDSTONE CANYON',detail:'SOUTHWEST · 07:18 AM',spot:'The Painted<br>Bend',copy:'Warm currents curl beneath the red cliffs.<br>Big shadows move in the deep.',temp:'24°',weather:'SUNNY · LIGHT BREEZE',water:'21° C',depth:'11.2 m',sky:['#efb879','#ce8e69','#9e7564'],hills:['#995d42','#754c3b','#4a453b'],water:'#537778',fish:[['Channel Catfish','Largemouth Bass','Bluegill','Carp','Striped Bass','Smallmouth Bass','Flathead Catfish','Gar','Redear Sunfish','Crappie','Longnose Gar','Freshwater Drum','Paddlefish','White Bass','Bowfin','Buffalo Fish','Alligator Gar','Golden Shiner']]},
    {name:'ALPINE GLACIER',detail:'NORTHERN RANGE · 05:56 AM',spot:'The Blue<br>Below',copy:'Ice-cold water, ancient stone, and a<br>silence that reaches for miles.',temp:'9°',weather:'HIGH CLOUD · CALM',water:'6° C',depth:'18.8 m',sky:['#9abac1','#abc7c5','#6a9caa'],hills:['#708782','#526b69','#354f55'],water:'#386878',fish:[['Arctic Char','Lake Trout','Grayling','Cutthroat Trout','Whitefish','Burbot','Dolly Varden','Kokanee Salmon','Bull Trout','Brook Trout','Mountain Whitefish','Northern Pike','Cisco','Inconnu','Tiger Trout','Golden Trout','Brown Trout','Rainbow Trout']]},
    {name:'MOONLIT BAY',detail:'COASTAL WILDS · 08:11 PM',spot:'The Last<br>Light',copy:'A tidal inlet at the edge of the wild.<br>Listen for the splash in the dark.',temp:'16°',weather:'OVERCAST · MIST',water:'12° C',depth:'9.7 m',sky:['#827d89','#586878','#283f52'],hills:['#3f4b4b','#303e44','#1c323b'],water:'#294d59',fish:[['Coho Salmon','Striped Bass','Flounder','Sea-run Trout','Bluefish','Red Drum','Snook','Halibut','King Salmon','Mackerel','Black Drum','Weakfish','Tarpon','Spotted Seatrout','Sheepshead','Jack Crevalle','Cobia','Atlantic Salmon']]}
  ];
  const state={map:0,phase:'idle',target:{x:.69,y:.58},castAt:0,biteAt:0,timer:null,fish:null,progress:0,tension:0.38,holding:false,last:0,catchCount:0,streak:0,found:new Set(['Rainbow Trout','Brook Trout','Largemouth Bass']),day:0,toastTimer:null,sound:true,boatX:.5,boatY:0};
  const rand=(a,b)=>a+Math.random()*(b-a), clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
  let W=0,H=0,dpr=1;
  function resize(){const r=canvas.getBoundingClientRect();W=r.width;H=r.height;dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}
  addEventListener('resize',resize);resize();
  function polygon(points,color){ctx.fillStyle=color;ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.closePath();ctx.fill()}
  function drawScene(t){const m=maps[state.map],time=t*.001,w=W,h=H;
    const sky=ctx.createLinearGradient(0,0,0,h*.64);sky.addColorStop(0,m.sky[0]);sky.addColorStop(.55,m.sky[1]);sky.addColorStop(1,m.sky[2]);ctx.fillStyle=sky;ctx.fillRect(0,0,w,h);
    // dawn glow
    const glow=ctx.createRadialGradient(w*.69,h*.28,2,w*.69,h*.28,w*.42);glow.addColorStop(0,'rgba(255,230,177,.55)');glow.addColorStop(.18,'rgba(255,219,168,.21)');glow.addColorStop(1,'rgba(255,220,170,0)');ctx.fillStyle=glow;ctx.fillRect(0,0,w,h*.72);
    ctx.fillStyle='rgba(255,232,185,.82)';ctx.beginPath();ctx.arc(w*.69,h*.285,Math.min(w,h)*.044,0,Math.PI*2);ctx.fill();
    // distant ridges
    polygon([[0,h*.48],[0,h*.36],[w*.08,h*.32],[w*.15,h*.37],[w*.25,h*.25],[w*.34,h*.36],[w*.47,h*.28],[w*.58,h*.39],[w*.70,h*.29],[w*.82,h*.37],[w*.91,h*.3],[w,h*.35],[w,h*.51]],m.hills[0]);
    polygon([[0,h*.49],[0,h*.405],[w*.12,h*.38],[w*.23,h*.42],[w*.35,h*.34],[w*.45,h*.41],[w*.61,h*.35],[w*.73,h*.42],[w*.88,h*.36],[w,h*.4],[w,h*.52]],m.hills[1]);
    // snow / rock crests
    if(state.map===2){polygon([[w*.17,h*.39],[w*.25,h*.25],[w*.29,h*.34],[w*.255,h*.315],[w*.24,h*.35],[w*.223,h*.326]],'rgba(235,240,222,.78)');polygon([[w*.63,h*.39],[w*.70,h*.29],[w*.76,h*.39],[w*.70,h*.335],[w*.682,h*.36]],'rgba(235,240,222,.7)')}
    // pine silhouettes shore
    for(let i=0;i<32;i++){const x=((i*137.7)%w),base=h*(.484+Math.sin(i*12.7)*.035),scale=(.45+((i*37)%57)/100)*Math.max(.7,w/1000);if(x>w*.2&&x<w*.79&&i%3)continue;drawTree(x,base,scale,m.hills[2],i)}
    const waterTop=h*.48, water=ctx.createLinearGradient(0,waterTop,0,h);water.addColorStop(0,m.water);water.addColorStop(.38,'#244c52');water.addColorStop(1,'#122f38');ctx.fillStyle=water;ctx.fillRect(0,waterTop,w,h-waterTop);
    // shimmering reflections
    for(let i=0;i<95;i++){let yy=waterTop+((i*47+time*16)%Math.max(1,h-waterTop)),x=((i*193.3+Math.sin(time*.6+i)*22)%w);let len=(12+(i*29)%82)*(yy/h);ctx.strokeStyle=`rgba(222,224,190,${.025+((i*13)%17)/350})`;ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x,yy);ctx.lineTo(x+len,yy+randStable(i)*1.5);ctx.stroke()}
    // sun path
    for(let i=0;i<15;i++){let y=waterTop+15+i*i*1.1;let width=90-i*4;ctx.strokeStyle=`rgba(255,220,166,${.14-i*.007})`;ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(w*.69-width/2,y+Math.sin(time+i)*3);ctx.lineTo(w*.69+width/2,y);ctx.stroke()}
    // surface ripples and occasional fish dimples
    for(let i=0;i<8;i++){const x=(w*(.18+i*.105)+Math.sin(time*.32+i*4)*18);const y=waterTop+30+((i*51)%Math.max(60,h*.23));ctx.strokeStyle='rgba(197,218,203,.16)';ctx.beginPath();ctx.ellipse(x,y,8+Math.sin(time+i)*4,2,0,0,Math.PI*2);ctx.stroke()}
    if(state.phase==='waiting'||state.phase==='bite'||state.phase==='fight') drawBobber(time);
    drawBoat(time);
    if(state.phase==='fight')drawFishOnLine(time);
    if(state.phase==='caught'){}
    requestAnimationFrame(drawScene);
  }
  function randStable(i){return ((i*17)%11)/11}
  function drawTree(x,y,s,color,i){ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(x,y-s*62);ctx.lineTo(x-s*21,y-s*22);ctx.lineTo(x-s*12,y-s*23);ctx.lineTo(x-s*28,y-s*4);ctx.lineTo(x+s*28,y-s*4);ctx.lineTo(x+s*12,y-s*23);ctx.lineTo(x+s*20,y-s*22);ctx.closePath();ctx.fill();ctx.fillRect(x-s*2,y-s*5,s*4,s*12)}
  function drawBobber(time){let x=state.target.x*W,y=state.target.y*H,scale=.65+y/H*.7;ctx.strokeStyle='rgba(238,237,214,.55)';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(W*.53,H*.91);ctx.quadraticCurveTo(W*.61,H*.72,x,y);ctx.stroke();ctx.fillStyle='rgba(236,225,199,.18)';ctx.beginPath();ctx.ellipse(x,y+3,10*scale,2.4*scale,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#efe4c9';ctx.beginPath();ctx.ellipse(x,y,3.8*scale,6*scale,0,Math.PI,0);ctx.fill();ctx.fillStyle=state.phase==='bite'?'#f58e65':'#d99b69';ctx.beginPath();ctx.ellipse(x,y,3.8*scale,5*scale,0,0,Math.PI);ctx.fill();if(state.phase==='bite'){ctx.globalAlpha=.35+Math.sin(time*10)*.24;ctx.strokeStyle='#ffcb85';ctx.beginPath();ctx.ellipse(x,y,13+Math.sin(time*7)*4,5,0,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=1}}
  function drawBoat(time){let x=W*(.52+state.boatX*.12),y=H*.91+Math.sin(time*1.15)*2,s=Math.max(.65,Math.min(1,W/1050));ctx.save();ctx.translate(x,y);ctx.scale(s,s);ctx.fillStyle='rgba(5,19,23,.32)';ctx.beginPath();ctx.ellipse(0,10,75,12,0,0,Math.PI*2);ctx.fill();polygon([[-83,-5],[-58,-17],[45,-15],[79,-4],[63,7],[-52,9]],'#644f3a');polygon([[-68,-4],[-49,-12],[42,-11],[65,-4],[48,2],[-48,3]],'#b59b70');ctx.strokeStyle='rgba(237,219,173,.58)';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(-53,-8);ctx.lineTo(45,-8);ctx.stroke();ctx.fillStyle='#263a38';ctx.fillRect(-18,-24,36,13);ctx.fillStyle='#9e8d6a';ctx.fillRect(-14,-29,28,8);ctx.fillStyle='rgba(209,224,211,.55)';ctx.fillRect(-10,-27,20,5);ctx.strokeStyle='#392f29';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(20,-16);ctx.lineTo(54,-80);ctx.stroke();ctx.strokeStyle='rgba(239,231,207,.7)';ctx.lineWidth=.8;ctx.beginPath();ctx.moveTo(54,-80);ctx.quadraticCurveTo(57,-25,state.target.x*W-x,state.target.y*H-y);ctx.stroke();ctx.restore()}
  function drawFishOnLine(time){const x=state.target.x*W,y=state.target.y*H+16+Math.sin(time*9)*5;drawFish(x,y,22+state.progress*8,Math.sin(time*11)*.4,state.fish?.color||'#c6a674')}
  function drawFish(x,y,size,angle,color){ctx.save();ctx.translate(x,y);ctx.rotate(angle);ctx.fillStyle=color;ctx.beginPath();ctx.ellipse(0,0,size,size*.43,0,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.moveTo(-size*.76,0);ctx.lineTo(-size*1.2,-size*.46);ctx.lineTo(-size*1.14,size*.46);ctx.closePath();ctx.fill();ctx.fillStyle='rgba(242,218,155,.75)';ctx.beginPath();ctx.ellipse(size*.3,0,size*.25,size*.1,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#f6edd4';ctx.beginPath();ctx.arc(size*.6,-size*.1,Math.max(1.7,size*.055),0,Math.PI*2);ctx.fill();ctx.fillStyle='#192d30';ctx.beginPath();ctx.arc(size*.62,-size*.1,Math.max(1,size*.028),0,Math.PI*2);ctx.fill();ctx.restore()}
  requestAnimationFrame(drawScene);

  const speciesMeta={
    'Rainbow Trout':['🐟','TROUT · COMMON','#c9946f'],'Brook Trout':['🐟','TROUT · COMMON','#8d755a'],'Largemouth Bass':['🐠','BASS · UNCOMMON','#82915e'],'Yellow Perch':['🐟','PERCH · COMMON','#c9a754'],'Northern Pike':['🐊','PIKE · RARE','#97a475'],'Bluegill':['🐠','PANFISH · COMMON','#8b81a2'],'Lake Sturgeon':['🦈','STURGEON · LEGENDARY','#858b7b'],'Walleye':['🐟','WALLEYE · UNCOMMON','#a79c6c'],'Brown Trout':['🐟','TROUT · UNCOMMON','#9f7959'],'Smallmouth Bass':['🐠','BASS · UNCOMMON','#a29068'],'Whitefish':['🐟','WHITEFISH · COMMON','#b1aa8c'],'Muskellunge':['🐊','MUSKIE · LEGENDARY','#827b58'],'Kokanee Salmon':['🐟','SALMON · RARE','#bd6554'],'Catfish':['🐟','CATFISH · UNCOMMON','#8b7b68'],'Tiger Trout':['🐟','TROUT · RARE','#d8a56c'],'Bull Trout':['🐟','TROUT · RARE','#af755e'],'Arctic Char':['🐟','CHAR · RARE','#bd836d'],'Golden Trout':['🐟','TROUT · LEGENDARY','#d8bd77']};
  function setMessage(title,sub){$('message-title').textContent=title;$('message-sub').textContent=sub;$('center-message').style.opacity=title?1:0}
  function toast(text){const e=$('toast');e.textContent=text;e.classList.add('show');clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>e.classList.remove('show'),2300)}
  function updateMap(){const m=maps[state.map];$('map-name').textContent=m.name;$('map-detail').textContent=m.detail;$('spot-title').innerHTML=m.spot;$('spot-copy').innerHTML=m.copy;$('temp').textContent=m.temp;$('weather-text').textContent=m.weather;$('water-temp').textContent=m.water;$('depth-value').textContent=m.depth;$('map-btn').querySelector('.map-label').innerHTML=`Explore waters <b>→</b>`}
  function updateHud(){$('species-count').textContent=String(state.found.size).padStart(2,'0');$('streak').textContent=state.streak;$('session-label').textContent=state.phase==='fight'?'Fish on the line':state.phase==='bite'?'A fish is biting':'A quiet morning';$('line-label').textContent=state.phase==='idle'?'LINE READY':state.phase==='waiting'?'LINE IN WATER':state.phase==='bite'?'BITE! STRIKE NOW':state.phase==='fight'?'FISH ON · REEL':'CATCH SECURED';}
  function cast(x,y){if(state.phase!=='idle')return;state.phase='casting';state.target={x:clamp(x,.3,.88),y:clamp(y,.51,.78)};setMessage('');updateHud();$('cast-btn').style.display='none';toast('Nice cast — now we wait.');setTimeout(()=>{if(state.phase!=='casting')return;state.phase='waiting';setMessage('The water is yours.','Watch the bobber. Listen for the tug.');updateHud();state.timer=setTimeout(bite,rand(4500,10500))},650)}
  function bite(){if(state.phase!=='waiting')return;state.phase='bite';state.biteAt=performance.now();state.fish=chooseFish();setMessage('You have a bite!','Strike now — press SPACE or tap the button');$('cast-btn').style.display='flex';$('cast-btn').querySelector('.cast-text').innerHTML='STRIKE!<small>SPACE</small>';updateHud();state.timer=setTimeout(()=>{if(state.phase==='bite'){state.phase='idle';state.streak=0;setMessage('It got away.','The lake is full of second chances.');resetButton();updateHud();toast('Too slow! Cast again when you are ready.')}},4300)}
  function chooseFish(){let pool=maps[state.map].fish[0],name=pool[Math.floor(Math.random()*pool.length)];const colors=['#c9946f','#9da975','#c6b47f','#bd806d','#859c92'];return{name,weight:rand(.35,6.8),length:rand(18,77),color:colors[Math.floor(Math.random()*colors.length)],rarity:(speciesMeta[name]?.[1]||'FISH · UNCOMMON').split(' · ')[1]}}
  function strike(){if(state.phase==='bite'){clearTimeout(state.timer);state.phase='fight';state.progress=.12;state.tension=.38;state.last=performance.now();$('cast-btn').style.display='none';$('reel-btn').classList.add('active');$('tension-wrap').classList.add('active');setMessage('Keep the line.','Hold REEL IN when the fish tires.');updateHud();return}if(state.phase==='idle')cast(.7,.57)}
  function resetButton(){$('cast-btn').style.display='flex';$('cast-btn').querySelector('.cast-text').innerHTML='CAST LINE<small>SPACE</small>';$('reel-btn').classList.remove('active');$('tension-wrap').classList.remove('active');state.holding=false}
  function finishCatch(){state.phase='caught';state.progress=1;state.catchCount++;state.streak++;state.found.add(state.fish.name);updateHud();setMessage('A beautiful catch.','Take a moment with this one.');$('reel-btn').classList.remove('active');$('tension-wrap').classList.remove('active');setTimeout(showCatch,450)}
  function showCatch(){if(state.phase!=='caught')return;let f=state.fish,meta=speciesMeta[f.name]||['🐟','FRESHWATER · UNCOMMON',f.color];openModal(`<div class="catch-result"><div class="modal-kicker">✦ &nbsp; A NEW MEMORY</div><div class="trophy">${meta[0]}</div><h2>Well caught.</h2><div class="catch-fish">${f.name}</div><div class="catch-stats"><span><b>${f.weight.toFixed(1)} lb</b><small>WEIGHT</small></span><span><b>${Math.round(f.length)} cm</b><small>LENGTH</small></span><span><b>${meta[1].split(' · ')[1]}</b><small>RARITY</small></span></div><p class="modal-intro">A lovely ${f.name.toLowerCase()} from ${maps[state.map].name.toLowerCase()}. Release it back into the water?</p><button class="modal-action" id="release-btn">RELEASE WITH CARE &nbsp; →</button></div>`);$('release-btn').onclick=()=>{closeModal();state.phase='idle';state.fish=null;resetButton();setMessage('The water is yours.','Cast into the morning.');updateHud();toast('Released safely. The story stays with you.')};}
  function openModal(html){$('modal-content').innerHTML=html;$('modal-backdrop').classList.add('open')}
  function closeModal(){$('modal-backdrop').classList.remove('open')}
  function showJournal(){let all=[...new Set(maps.flatMap(m=>m.fish[0]))];openModal(`<div class="modal-kicker">YOUR FIELD NOTES · ${state.found.size} / ${all.length}</div><h2>The Field Journal</h2><p class="modal-intro">Every fish is a story. Keep exploring to fill the pages.</p><div class="species-grid">${all.slice(0,18).map(n=>{let known=state.found.has(n),meta=speciesMeta[n]||['🐟','FRESHWATER · UNKNOWN'];return `<div class="species-item ${known?'':'locked'}"><span class="fish-emoji">${known?meta[0]:'?'}</span><b>${known?n:'Undiscovered'}</b><small>${known?meta[1]:'SPECIES UNKNOWN'}</small></div>`}).join('')}</div>`)}
  function showMaps(){openModal(`<div class="modal-kicker">FOUR WATERS · FOUR STORIES</div><h2>Choose your waters</h2><p class="modal-intro">Each place has its own fish, weather, and secrets.</p><div class="map-grid">${maps.map((m,i)=>`<button class="map-option ${state.map===i?'selected':''}" data-map="${i}"><b>${m.name.replace(' ','\n')}</b><span>${['PINE FOREST · TROUT & BASS','RED ROCK · CATFISH & GAR','HIGH ALPINE · COLDWATER','COASTAL · SALMON & MORE'][i]}</span><span class="map-lock">${state.map===i?'✓':'↗'}</span></button>`).join('')}</div>`);document.querySelectorAll('[data-map]').forEach(b=>b.onclick=()=>{state.map=Number(b.dataset.map);updateMap();closeModal();state.boatX=rand(-.4,.4);toast(`Now exploring ${maps[state.map].name}.`);setMessage('A new water.','Take your time and find the fish.');})}

  // Reel loop: safely pump the line rather than holding against a hard-running fish.
  let lastFrame=performance.now();function updateFight(now){const dt=Math.min(.05,(now-lastFrame)/1000);lastFrame=now;if(state.phase==='fight'){const run=Math.sin(now*.0018+state.progress*12)>0.42;state.tension=clamp(state.tension+(state.holding?(run?.018:-.014):(run?-.013:-.004))*dt*16,0,1);if(state.holding&&!run)state.progress+=dt*(.07+Math.random()*.025);if(run&&!state.holding)state.progress+=dt*.009;if(state.tension>.88){state.phase='idle';state.streak=0;state.fish=null;resetButton();setMessage('The line snapped.','Give the fish room when it runs.');toast('Line tension was too high. Try again!');updateHud()}else if(state.progress>=1)finishCatch();$('tension-bar').style.left=`${state.tension*94+3}%`;$('tension-text').textContent=state.tension>.76?'TOO TIGHT':state.tension<.23?'GOING SLACK':'STEADY';$('tension-text').style.color=state.tension>.76?'#e78767':state.tension<.23?'#e6d090':'#c7d7b1'}requestAnimationFrame(updateFight)}requestAnimationFrame(updateFight);
  canvas.addEventListener('pointerdown',e=>{if(state.phase==='idle'){const r=canvas.getBoundingClientRect();cast((e.clientX-r.left)/r.width,(e.clientY-r.top)/r.height)}});
  $('cast-btn').addEventListener('click',strike);const reel=$('reel-btn');reel.addEventListener('pointerdown',e=>{e.preventDefault();state.holding=true});['pointerup','pointerleave','pointercancel'].forEach(ev=>reel.addEventListener(ev,()=>state.holding=false));
  document.addEventListener('keydown',e=>{if(e.code==='Space'){e.preventDefault();if(!$('modal-backdrop').classList.contains('open'))strike()}if(e.code==='KeyW'||e.code==='KeyA'||e.code==='KeyS'||e.code==='KeyD'){state.boatX=clamp(state.boatX+(e.code==='KeyA'?.04:e.code==='KeyD'?-.04:0),-.4,.4);if(state.phase==='idle'&&e.code==='KeyW')toast('Finding a quiet spot...')}});
  $('map-btn').onclick=showMaps;$('book-btn').onclick=showJournal;$('modal-close').onclick=closeModal;$('modal-backdrop').addEventListener('click',e=>{if(e.target===$('modal-backdrop'))closeModal()});$('sound-btn').onclick=()=>{state.sound=!state.sound;$('sound-btn').textContent=state.sound?'♫':'♪';toast(state.sound?'Sound on':'Sound off')};
  updateMap();updateHud();setInterval(()=>{state.day++;let mins=42+state.day,hr=6+Math.floor(mins/60);mins%=60;$('clock').textContent=`${String(hr%12||12).padStart(2,'0')}:${String(mins).padStart(2,'0')}`},60000);
})();

