await (async page => {const releaseVisible=await page.locator("#release-btn").isVisible();const fish=await page.locator(".catch-fish").innerText();await page.locator("#release-btn").click();await page.locator("#book-btn").click();const summary=await page.locator(".modal-kicker").innerText();const fishCount=await page.locator(".species-item").count();const mobileOverflow=await page.evaluate(()=>document.documentElement.scrollWidth>document.documentElement.clientWidth);await page.screenshot({path:"screenshots/latest.jpg"});return {releaseVisible,fish,summary,fishCount,mobileOverflow};})(page);
